def _parse_flags(flags):
    return {flag for flag in flags.split() if flag in {"-i", "-l", "-n", "-v", "-x"}}


def _matches(text, pattern, flags):
    if "-i" in flags:
        text = text.casefold()
        pattern = pattern.casefold()

    if "-x" in flags:
        matched = text == pattern
    else:
        matched = pattern in text

    return not matched if "-v" in flags else matched


def _format_line(filename, lineno, text, show_file, show_lineno):
    prefix = ""
    if show_file:
        prefix += f"{filename}:"
    if show_lineno:
        prefix += f"{lineno}:"
    return f"{prefix}{text}\n"


def grep(pattern, flags, files):
    flag_set = _parse_flags(flags)
    show_file = len(files) > 1
    output = []

    for filename in files:
        matched_file = False

        with open(filename) as file_handle:
            for lineno, raw_line in enumerate(file_handle, start=1):
                line = raw_line.rstrip("\r\n")
                if not _matches(line, pattern, flag_set):
                    continue

                matched_file = True
                if "-l" in flag_set:
                    break

                output.append(
                    _format_line(
                        filename,
                        lineno,
                        line,
                        show_file,
                        "-n" in flag_set,
                    )
                )

        if "-l" in flag_set and matched_file:
            output.append(f"{filename}\n")

    return "".join(output)

